package app.planaloud;
import android.widget.*;
import android.graphics.drawable.GradientDrawable;
import java.util.Arrays;
final class PaletteSettings {
    static void show(MainActivity a){LinearLayout page=a.fullPage("事件默认色系",()->new SettingsPanels(a).appearance());page.addView(Ui.text(a,"事件默认色系",22,true));page.addView(Ui.help(a,"同一事件在应用与桌面组件中使用同一颜色，深色模式不会改变事件颜色。手动指定的颜色优先；切换色系后，自动配色的已有事件同步更新。"));Spinner choice=TaskTypes.spinner(a,page,"默认色系",Arrays.asList(EventPalette.LABELS));choice.setSelection(Math.max(0,Arrays.asList(EventPalette.VALUES).indexOf(EventPalette.selected())));LinearLayout samples=Ui.column(a);page.addView(samples);choice.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> parent,android.view.View view,int index,long id){samples.removeAllViews();for(int row=0;row<3;row++){LinearLayout line=Ui.row(a);samples.addView(line);for(int col=0;col<4;col++){int color=EventPalette.at(EventPalette.VALUES[index],row*4+col);TextView swatch=new TextView(a);swatch.setContentDescription(String.format("#%06X",color&0xffffff));GradientDrawable bg=new GradientDrawable();bg.setColor(color);bg.setCornerRadius(Ui.dp(a,10));swatch.setBackground(bg);LinearLayout.LayoutParams at=new LinearLayout.LayoutParams(0,Ui.dp(a,48),1);at.setMargins(Ui.dp(a,3),Ui.dp(a,3),Ui.dp(a,3),Ui.dp(a,3));line.addView(swatch,at);}}}public void onNothingSelected(AdapterView<?> parent){}});page.addView(Ui.button(a,"保存色系",true,()->{a.prefs.edit().putString("event_palette",EventPalette.VALUES[choice.getSelectedItemPosition()]).apply();AgendaWidget.refresh(a);a.message("已保存，应用与组件同步使用此色系");}));}
}
